<?php
$r=dirname(__DIR__);$d=$r.'/outputs/project-publication/installer-test-'.bin2hex(random_bytes(4));mkdir($d,0775,true);$site=$d.'/site';mkdir($site.'/app',0775,true);file_put_contents($site.'/app/old.php','<?php echo "old";');file_put_contents($site.'/app/remove.php','<?php echo "remove";');
foreach(['rollback','success']as$mode){$pkg=$d.'/'.$mode;mkdir($pkg.'/files/app',0775,true);copy($r.'/scripts/install_project_publication.php',$pkg.'/install.php');file_put_contents($pkg.'/files/app/old.php','<?php echo "new";');file_put_contents($pkg.'/files/app/new.php','<?php echo "added";');$manifest=['app/old.php'=>['before'=>hash_file('sha256',$site.'/app/old.php'),'after'=>hash_file('sha256',$pkg.'/files/app/old.php')],'app/new.php'=>['before'=>null,'after'=>hash_file('sha256',$pkg.'/files/app/new.php')],'app/remove.php'=>['before'=>hash_file('sha256',$site.'/app/remove.php'),'after'=>null]];file_put_contents($pkg.'/manifest.json',json_encode($manifest));if($mode==='rollback')file_put_contents($pkg.'/smoke.php','<?php exit(9);');putenv('PROJECT_RELEASE_TEST_ROOT='.$site);exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($pkg.'/install.php').' 2>&1',$out,$code);putenv('PROJECT_RELEASE_TEST_ROOT');if($mode==='rollback'){if(!$code||file_get_contents($site.'/app/old.php')!=='<?php echo "old";'||is_file($site.'/app/new.php')||!is_file($site.'/app/remove.php'))throw new RuntimeException('Rollback failed');}else{if($code||!is_file($pkg.'/receipt.json')||is_file($site.'/app/remove.php')||!is_file($site.'/app/new.php'))throw new RuntimeException('Install failed');}}echo "Release installer: successful publication and full rollback verified\n";
